import React from "react";

const RuleConfig = ({ rules }) => {
  return (
    <div className="card">
      <h3>Dynamic Rules Configuration</h3>
      <div className="rules-grid">
        {Object.entries(rules).map(([type, config]) => (
          <div className="rule-item" key={type}>
            <h4>{type}</h4>
            <ul>
              {config.escalate_if_count && (
                <li>Escalate if count &ge; {config.escalate_if_count}</li>
              )}
              {config.window_mins && <li>Window: {config.window_mins} mins</li>}
              {config.expire_after_mins && (
                <li>Auto-close after: {config.expire_after_mins} mins</li>
              )}
              {config.auto_close_if && (
                <li>Auto-close condition: {config.auto_close_if} = true</li>
              )}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
};

export default RuleConfig;
/*
  {  "overspeed" :  {"escalate_if_count": 3,"window_mins": 60,"expire_after_mins": 1440},
     "feedback_negative": {"escalate_if_count": 2,"window_mins": 1440,"expire_after_mins": 2880},
     "compliance":  {"auto_close_if": "document_valid","expire_after_mins": 1440 }
  }
*/